import json
data = json.load(open('/app/resources/treasury_bulletin_1990_09.json'))
elements = data['document'].get('elements', [])

# Find all text on page_id 19 with their exact coordinates
page19_text = []
for e in elements:
    if e.get('type') == 'text':
        content = e.get('content', '')
        if content:
            bbox = e.get('bbox', [])
            for b in bbox:
                if b.get('page_id') == 19:
                    coord = b.get('coord', [])
                    page19_text.append((coord[1] if coord else 0, content))

# Sort by Y coordinate (row position on page)
page19_text.sort()

for y, content in page19_text:
    print(f'Y={int(y)}: {content[:100]}')
"
